3	import (
4		"testing"
5	
6		"github.com/immuta/operations/services/crow/pkg/api"
7	)
8	
9	func mod(version string) api.Module {
10		return api.Module{
11			ModuleIdentifier: api.ModuleIdentifier{Namespace: "iac", Name: "comply", Provider: "aws"},
12			Version:          version,
13		}
14	}
15	
16	func TestMemCacheRoundTrip(t *testing.T) {
17		c := NewMemCache()
18		if _, ok, err := c.Get(mod("1.0.0")); err != nil || ok {
19			t.Fatalf("expected miss; got ok=%v err=%v", ok, err)
20		}
21		if err := c.Put(mod("1.0.0"), []byte("payload")); err != nil {
22			t.Fatalf("Put: %v", err)
23		}
24		got, ok, err := c.Get(mod("1.0.0"))
25		if err != nil || !ok {
26			t.Fatalf("expected hit; got ok=%v err=%v", ok, err)
27		}
28		if string(got) != "payload" {
29			t.Errorf("body = %q", got)
30		}
31	}
32	
33	func TestDiskCacheMissThenHit(t *testing.T) {
34		dir := t.TempDir()
35		c, err := NewDiskCache(dir)
36		if err != nil {
37			t.Fatalf("NewDiskCache: %v", err)
38		}
39		if _, ok, err := c.Get(mod("1.0.0")); err != nil || ok {
40			t.Fatalf("expected miss; got ok=%v err=%v", ok, err)
41		}
42		if err := c.Put(mod("1.0.0"), []byte("disk-payload")); err != nil {
43			t.Fatalf("Put: %v", err)
44		}
45		got, ok, err := c.Get(mod("1.0.0"))
46		if err != nil || !ok {
47			t.Fatalf("expected hit; got ok=%v err=%v", ok, err)
48		}
49		if string(got) != "disk-payload" {
50			t.Errorf("body = %q", got)
51		}
52	}
53	
54	func TestDiskCacheSurvivesNewInstance(t *testing.T) {
55		dir := t.TempDir()
56		c1, _ := NewDiskCache(dir)
57		if err := c1.Put(mod("2.0.0"), []byte("persisted")); err != nil {
58			t.Fatal(err)
59		}
60		c2, _ := NewDiskCache(dir)
61		got, ok, err := c2.Get(mod("2.0.0"))
62		if err != nil || !ok {
63			t.Fatalf("expected hit; got ok=%v err=%v", ok, err)
64		}
65		if string(got) != "persisted" {
66			t.Errorf("body = %q", got)
67		}
68	}
